(()=>{const rows=[],cap=(n,f)=>{try{rows.push([n,{value:f()}])}catch(e){rows.push([n,{error:e.name,message:e.message,realm:e instanceof TypeError}])}};for(const key of['captured','inputs','pathname','groups','input'])cap('setter-'+key,()=>{const log=[];let result;Object.defineProperty(Object.prototype,key,{set(value){log.push({isArray:Array.isArray(value),type:typeof value,realm:value!==null&&typeof value==='object'?Object.getPrototypeOf(value)===Object.prototype:null});},configurable:true});try{result=new URLPattern({pathname:'/:captured'}).exec({pathname:'/x'})}finally{delete Object.prototype[key]}return{log,own:Object.getOwnPropertyNames(result),pathOwn:result.pathname?Object.getOwnPropertyNames(result.pathname):null,groupOwn:result.pathname?.groups?Object.getOwnPropertyNames(result.pathname.groups):null}});cap('proto-name',()=>{const r=new URLPattern({pathname:'/:__proto__'}).exec({pathname:'/x'});return{own:Object.getOwnPropertyNames(r.pathname.groups),prototype:Object.getPrototypeOf(r.pathname.groups)===Object.prototype}});return JSON.stringify(rows)})()
